struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    o.uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(o.uv * 2.0f - 1.0f, 0.0f, 1.0f);
    o.uv.y = 1.0f - o.uv.y;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

float pattern(float2 uv, float t)
{
    float v = 0.0f;
    v += sin(uv.x * 10.0f + t) * 0.5f;
    v += sin(uv.y * 8.0f + t * 1.3f) * 0.5f;
    v += sin((uv.x + uv.y) * 6.0f + t * 0.7f) * 0.5f;
    v += sin(length(uv - 0.5f) * 12.0f - t * 2.0f) * 0.5f;
    return v * 0.25f + 0.5f;
}

float3 proceduralScene(float2 uv, float t)
{
    float p = pattern(uv, t);
    float3 col;
    col.r = p * (0.8f + 0.2f * sin(t));
    col.g = p * (0.6f + 0.4f * sin(t * 1.3f + 2.0f));
    col.b = p * (0.7f + 0.3f * cos(t * 0.8f));
    return col;
}

float4 PSMain(VSOut i) : SV_Target
{
    float t = time_sim_ms * 0.001f;
    float2 uv = i.uv;
    float2 center = float2(0.5f, 0.5f);
    float2 dir = uv - center;
    float dist = length(dir);
    float offset = dist * 0.03f;
    float2 uvR = uv + dir * offset;
    float2 uvG = uv;
    float2 uvB = uv - dir * offset;
    float r = proceduralScene(uvR, t).r;
    float g = proceduralScene(uvG, t).g;
    float b = proceduralScene(uvB, t).b;
    return float4(r, g, b, 1.0f);
}
